  await fs.writeFile(cssPath, css, 'utf8');
  await fs.writeFile(htmlPath, updatedHtml, 'utf8');
  nodeRepl.write(JSON.stringify({ htmlPath, cssPath, cssBytes: css.length }));
}","timeout_ms":30000}

